const news = [
 {id:'town',date:'ประกาศตัวอย่าง',category:'เมือง',title:'เดินชมเมืองก่อนเริ่มการผจญภัย',image:'01-spawn-crystal.webp',intro:'จากลานคริสตัลไปธนาคาร โรงตีเหล็ก และตลาด ทุกเส้นทางเริ่มจากจุดเดียวกัน',body:['ใช้แผนที่เพื่อค้นหาบริการและดูพิกัดของย่านต่าง ๆ','เดินตามถนนหลักไปยังธนาคาร โรงตีเหล็ก หรือหอรับรอง หากเพิ่งเริ่มเล่นให้แวะรับคู่มือก่อน','บทความนี้เป็นเนื้อหาตัวอย่างของเว็บ ยังไม่มีประกาศเปิดเซิร์ฟจริง']},
 {id:'rp',date:'แนวทางการเล่น',category:'ชุมชน',title:'Roleplay ได้ ในจังหวะของตัวเอง',image:'03-quest-lodge.webp',intro:'อยากเป็นนักผจญภัย พ่อค้า หรือนักตกปลา เลือกบทบาทที่ชอบได้เลย',body:['Luma วางแนวทางให้ roleplay เป็นทางเลือก ไม่บังคับใช้เสียงหรือเล่นตามบทตลอดเวลา','ร่วมเล่นบทกับคนที่ยินดี แยกข้อมูลในบทบาทกับนอกบทบาท และเคารพขอบเขตของผู้เล่นคนอื่น','เควส อาชีพ และการสำรวจยังเล่นแบบปกติได้ โดยไม่ต้องส่งประวัติตัวละครก่อนเข้า']},
 {id:'forge',date:'ระบบที่วางแผน',category:'ระบบ',title:'ซ่อมอุปกรณ์ พร้อมเห็นราคาก่อนจ่าย',image:'07-forge-repair.webp',intro:'เคาน์เตอร์เดียว ดูไอเทม ราคา และผลลัพธ์ก่อนยืนยัน',body:['หน้าซ่อมแสดงอุปกรณ์ที่เลือก คุณสมบัติเดิม ค่าใช้จ่าย และความทนทานหลังซ่อม','ระบบจริงต้องรักษาค่าคุณสมบัติ อัญมณี และหมายเลขไอเทม ไม่สร้างของใหม่จากแม่แบบแทนของเดิม','รายการนี้เป็นแผนระบบ ยังไม่ได้เปิดให้ผู้เล่นใช้งาน']}
];
const products = [
 {id:'halo-skin',name:'Aether Halo',type:'ของตกแต่ง',price:149,image:'item-aether-halo.webp',description:'วงแหวนรูนสำหรับตกแต่งตัวละคร รุ่นร้านค้าไม่มีโบนัสพลังหรือค่าโจมตี'},
 {id:'runeblade-skin',name:'Runeblade Skin',type:'ของตกแต่ง',price:99,image:'item-runeblade.webp',description:'รูปลักษณ์ดาบรูนสำหรับอาวุธที่มีอยู่แล้ว ไม่มีอาวุธหรือค่าโจมตีเพิ่ม'}
];
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog'),dialogContent=document.querySelector('#dialog-content');
let activeZone='spawn', mapScale=1, mapPan=[0,0], selectedCategory='ทั้งหมด';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=text=>{const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3500)};
function modal(html){dialogContent.innerHTML=html;dialog.showModal()}
document.querySelector('#close-dialog').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let savedTheme;try{savedTheme=localStorage.getItem('luma-theme')}catch{}
document.documentElement.dataset.theme=savedTheme || 'dark';
function themeLabel(){document.querySelector('#theme').textContent=document.documentElement.dataset.theme==='light'?'โหมดมืด':'โหมดสว่าง'}
themeLabel();document.querySelector('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('luma-theme',theme)}catch{}themeLabel()};
function map(){return `<div class="shell"><div class="page-head"><p class="meta">TOWN DIRECTORY</p><h1>หาเส้นทางของคุณ</h1><p>ค้นหาธนาคาร จุดซ่อม ตลาด และบริการต่าง ๆ ในเมือง</p></div><div class="toolbar"><div class="field grow"><label for="zone-search">ค้นหาสถานที่หรือบริการ</label><input id="zone-search" type="search" placeholder="เช่น ธนาคาร ซ่อม ตกปลา" autocomplete="off"></div><div class="field"><label for="zone-type">ประเภท</label><select id="zone-type"><option>ทั้งหมด</option><option>บริการ</option><option>กิจกรรม</option><option>พักผ่อน</option><option>เมือง</option></select></div></div><div class="map-layout"><aside><p id="search-count" class="search-count"></p><div class="zone-list" id="zone-list"></div></aside><div><div class="map-viewport" id="map-viewport" aria-label="แผนผังตัวอย่างของเมือง"><div class="map-stage" id="map-stage"><img src="assets/city.webp" alt="ภาพเมืองสำหรับเลือกโซน">${zones.map((z,i)=>`<button class="map-pin ${z.id===activeZone?'active':''}" data-zone="${z.id}" style="left:${z.pin[0]}%;top:${z.pin[1]}%" aria-label="${z.name}">${i+1}</button>`).join('')}</div><div class="map-controls"><button data-zoom="1" aria-label="ขยายแผนที่">+</button><button data-zoom="-1" aria-label="ย่อแผนที่">−</button><button data-reset aria-label="คืนมุมมอง">↺</button></div><p class="map-note">แผนผังตัวอย่าง • จุดในภาพใช้เลือกโซน ไม่ใช่พิกัดจากโลกจริง</p></div><div class="zone-detail" id="zone-detail"></div></div></div><div class="status-box fine">แมพ 3D สดจะพร้อมเมื่อเชื่อมโลก Minecraft กับ BlueMap ภาพนี้ยังไม่ใช่ข้อมูลสด</div></div>`}
function mapTransform(){const stage=document.querySelector('#map-stage');if(stage)stage.style.transform=`translate(${mapPan[0]}px,${mapPan[1]}px) scale(${mapScale})`}
function updateMap(){const q=document.querySelector('#zone-search').value.trim().toLowerCase(),type=document.querySelector('#zone-type').value;const filtered=zones.filter(z=>(type==='ทั้งหมด'||z.type===type)&&[z.name,z.type,...z.services].join(' ').toLowerCase().includes(q));document.querySelector('#search-count').textContent=`${filtered.length} สถานที่`;document.querySelector('#zone-list').innerHTML=filtered.length?filtered.map(z=>`<button class="zone-button ${z.id===activeZone?'selected':''}" data-zone="${z.id}">${z.name}<small>${z.services.join(' / ')}</small></button>`).join(''):'<div class="empty">ไม่พบสถานที่ ลองค้นหาบริการอื่น</div>';const z=zones.find(z=>z.id===activeZone);document.querySelector('#zone-detail').innerHTML=`<div><h2>${z.name}</h2><p>${z.detail}</p><p class="fine">พิกัดแผน: X ${z.x}, Z ${z.z} / ${z.type}</p><div class="actions"><button class="button secondary" data-copy="${z.x}, ${z.z}">คัดลอกพิกัด</button><button class="text-button" data-zone-image="${z.id}">ดูภาพโซน</button></div></div><img src="assets/${z.image}" alt="ภาพคอนเซปต์ ${z.name}" width="1536" height="1024">`;document.querySelectorAll('.map-pin').forEach(p=>{p.classList.toggle('active',p.dataset.zone===activeZone);p.hidden=!filtered.some(z=>z.id===p.dataset.zone)})}
function newsPage(){return `<div class="shell"><div class="page-head"><p class="meta">JOURNAL</p><h1>ข่าวจาก Luma</h1><p>แนวทางเมือง ระบบ และกิจกรรมที่กำลังวางแผน</p></div><div class="pill-row">${['ทั้งหมด','เมือง','ชุมชน','ระบบ'].map(c=>`<button class="pill" data-category="${c}" aria-pressed="${selectedCategory===c}">${c}</button>`).join('')}</div><div class="news-grid" id="news-grid">${newsCards()}</div></div>`}
function newsCards(){return news.filter(n=>selectedCategory==='ทั้งหมด'||n.category===selectedCategory).map(n=>`<article class="news-card"><img src="assets/${n.image}" alt="${n.title}" width="1536" height="1024" loading="lazy"><span class="meta">${n.date}</span><h2>${n.title}</h2><p>${n.intro}</p><button data-news="${n.id}">อ่านต่อ</button></article>`).join('')}
function shop(){return `<div class="shell"><div class="page-head"><p class="meta">LUMA COSMETICS</p><h1>ของตกแต่งจากเมือง Luma</h1><p>ของตกแต่งและรูปลักษณ์สำหรับตัวละครในเมือง</p></div><p class="shop-note">สินค้าและราคาเป็นตัวอย่างสำหรับตรวจแบบ ยังไม่เปิดชำระเงินหรือส่งของเข้าเกม</p><div class="shop-grid">${products.map(p=>`<article><button class="product-image" data-product="${p.id}" aria-label="ดูรายละเอียด ${p.name}"><img src="assets/${p.image}" alt="ภาพอ้างอิง ${p.name}" width="1536" height="1024" loading="lazy"></button><div class="product-info"><div><h2 style="font-size:1.5rem">${p.name}</h2><p>${p.type} / ฿${p.price} ราคาเสนอ</p></div><button data-product="${p.id}">รายละเอียด</button></div></article>`).join('')}</div></div>`}
function render(){const route=location.hash.slice(1)||'home';if(route==='main'){main.focus();return}const pages={home:portalHome,map,news:newsPage,shop,account:portalAccount,wiki:wikiPage,events:eventsPage,rankings:rankingsPage,status:statusPage,privacy:()=>legalPage('privacy'),terms:()=>legalPage('terms')};main.innerHTML=(pages[route]||(()=>`<div class="shell"><h1>ไม่พบหน้านี้</h1><p>เลือกเมนูด้านบน หรือกลับไปเมือง Luma</p><a class="button" href="#home">กลับหน้าหลัก</a></div>`))();document.querySelectorAll('.nav nav a').forEach(a=>a.setAttribute('aria-current',a.hash===`#${route}`?'page':'false'));document.title=`Luma | ${{home:'เมืองของเรา',map:'แผนที่',news:'ข่าวสาร',shop:'ร้านค้า',account:'บัญชีของฉัน',wiki:'คู่มือเกม',events:'กิจกรรม',rankings:'อันดับผู้เล่น',status:'สถานะระบบ',privacy:'ความเป็นส่วนตัว',terms:'เงื่อนไขบริการ'}[route]||'เมืองของเรา'}`;if(route==='map'){updateMap();mapScale=1;mapPan=[0,0];const viewport=document.querySelector('#map-viewport');let drag;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag=[e.clientX,e.clientY,...mapPan];viewport.setPointerCapture(e.pointerId)});viewport.addEventListener('pointermove',e=>{if(!drag)return;mapPan=[Math.max(-300,Math.min(300,drag[2]+e.clientX-drag[0])),Math.max(-220,Math.min(220,drag[3]+e.clientY-drag[1]))];mapTransform()});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointercancel',()=>drag=null);document.querySelector('#zone-search').oninput=updateMap;document.querySelector('#zone-type').onchange=updateMap}syncAccountControls();window.scrollTo({top:0,behavior:'instant'});}
main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.zone){activeZone=b.dataset.zone;updateMap()}else if(b.dataset.zoom){mapScale=Math.max(1,Math.min(2.5,mapScale+Number(b.dataset.zoom)*.25));mapTransform()}else if(b.hasAttribute('data-reset')){mapScale=1;mapPan=[0,0];mapTransform()}else if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('คัดลอกพิกัดแล้ว')}catch{modal(`<h2 id="dialog-title">พิกัดสถานที่</h2><p>${escapeHTML(b.dataset.copy)}</p>`)}}else if(b.dataset.zoneImage){const z=zones.find(z=>z.id===b.dataset.zoneImage);modal(`<h2 id="dialog-title">${z.name}</h2><img src="assets/${z.image}" alt="${z.name}"><p>ภาพคอนเซปต์ ใช้แปลนพิกัดและขนาดจริงในการสร้าง</p>`)}else if(b.dataset.news){const n=news.find(n=>n.id===b.dataset.news);modal(`<article class="article"><span class="meta">${n.date}</span><h2 id="dialog-title">${n.title}</h2>${n.body.map(p=>`<p>${p}</p>`).join('')}</article>`)}else if(b.dataset.category){selectedCategory=b.dataset.category;document.querySelector('#news-grid').innerHTML=newsCards();document.querySelectorAll('[data-category]').forEach(a=>a.setAttribute('aria-pressed',a.dataset.category===selectedCategory))}else if(b.dataset.product){const p=products.find(p=>p.id===b.dataset.product);modal(`<h2 id="dialog-title">${p.name}</h2><p>${p.description}</p><p>ราคาเสนอ ฿${p.price} / ชำระครั้งเดียว</p><p>เมื่อเปิดบริการ: ยืนยันบัญชีเกม → ชำระผ่านผู้ให้บริการ → ตรวจรับเงิน → ส่งของอัตโนมัติ</p><button class="button" disabled>ยังไม่เปิดรับชำระ</button>`)}else if(b.hasAttribute('data-join')){modal('<h2 id="dialog-title">เตรียมพบกันที่ Luma</h2><p>เซิร์ฟอยู่ระหว่างวางแผน ยังไม่มี IP ที่เปิดให้เข้าเล่น</p><p>เป้าหมายรองรับ Minecraft Java 1.16.5 ขึ้นไป โดยตรวจความเข้ากันได้ก่อนประกาศรุ่นที่รองรับจริง</p>')}});
main.addEventListener('submit',e=>{if(e.target.id==='link-form'){e.preventDefault();document.querySelector('#link-error').textContent='ยังไม่เชื่อมเซิร์ฟเกม รหัสนี้จึงไม่ได้ถูกส่งหรือตรวจสอบ'}});
window.addEventListener('hashchange',render);render();
